e not 'cfrg';include kDialogRsrcName;include kPrintingRsrcName;include kDefaultRsrcName   'vers' (2);		// Overall package#if qDebuginclude kDebugRsrcName;#endif/* ==============================   Constants   ================================ */// Menu items numbers// #define mApple			1			// These are defined in MacAppTypes.r// #define mFile			2// #define mEdit			3#define mZoomy				4#define mWindows			6// Menu commands#define cNewFromSelection	1000#define cSlowAlgorithm		1009#define cFastAlgorithm		1010#define cZoomToSelection	1011// String list (STR#) resource numbers#define	kErrorStrings		1100#define	kAlgorithmStrings	1200// ID numbers for our palettes and color table#define	kClut				501#define	kTolerantPalette	1001#define	kAnimatingPalette	1002// IDs for some dialogs#define kMultiDialog		2002#define kAbout				4000#define kAbout2				4001#define kUnsupportedMac		-25001#define	kNo32BCQD			-25002#define kCompiledWrong		-25003#define kNoThreadManager	-25004/* ======================   Version Resource ('vers')   ======================== */// Version for the application or fileresource 'vers' (1,#if qNames	"Application Version",#endif	purgeable) {	0x03, 0x01, beta, 0x01,	verUs,	"3.1b1",	"FracApp 3.1b1, Copyright © 1988-1999 by Apple Computer, Inc"};/* ============================   Bundle Stuff   =============================== *//*	Now all the baggage required for the Icons at the Finder.  No real program	keeps the default Icon.*/type kSignature as 'STR ';resource kSignature (0, purgeable) {	"FracApp 3.1 ©Apple Computer, Inc. 1988-95"};resource 'BNDL' (128) {	kSignature, 0,	{		'ICN#', { 0, 128, 1, 129 },		'FREF', { 0, 128, 1, 129 }	}};resource 'FREF' (128) { 'APPL', 0, "" };resource 'FREF' (129) { kFileType, 1, "" };resource 'open' (128){	kSignature, { kFileType,  }};resource 'kind' (128){	kSignature,	verUS,	{		ftApplicationName, 	"FracApp",		kFileType,			"FracApp Document",	}};// Icon used for our applicationresource 'ICN#' (128) {	{		$"0000 0001 0000 0002 0000 0004 0040 0018 0020 0418 001C 03E0 001C 03E0 001F FFE0"		$"0007 FFE0 0007 FFE0 0007 FF90 0007 FF80 FFFF FF80 FFFF FF80 DFFF FF80 EFFF FF80"		$"F1FF FF80 F1FF FF80 F1FF FFE0 FE07 FFE0 FE07 C0E0 FE07 8050 FE07 3028 FE01 C810"		$"FE0E 7F8F FFE2 3007 FFFF 0007 FFFF 8007 FFFF E007 FFFF FFE7 FFFF F01F FFFF F007",		$"0000 0001 0000 0002 0000 0004 0040 0018 0020 0418 001C 03E0 001C 03E0 001F FFE0"		$"0007 FFE0 0007 FFE0 0007 FF90 0007 FF80 FFFF FF80 FFFF FF80 FFFF FF80 FFFF FF80"		$"FFFF FF80 FFFF FF80 FFFF FFE0 FFFF FFE0 FFFF FFE0 FFFF FFF0 FFFF FFF8 FFFF FFF0"		$"FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF FFFF F01F FFFF F007"	}};// Icon used for our documentsresource 'ICN#' (129) {	{		$"0FFF FC00 0C00 0200 0A00 0100 0980 0080 0982 0040 087C 03A0 087C 0390 087F FF90"		$"087F FE10 087F FE10 089F FE10 081F FE10 081F FFF0 081F FFF0 081F FFF0 081F FFF0"		$"081F FFF0 081F FFF0 087F FFF0 0870 FFF0 0870 FFF0 0880 FFF0 0900 FFF0 0800 FFF0"		$"0800 FFF0 0800 FFF0 0800 FFF0 0800 FFF0 0800 FFF0 0800 FFF0 0800 FFF0 0FFF FFF0",		$"0FFF FC00 0FFF FE00 0FFF FF00 0FFF FF80 0FFF FFC0 0FFF FFE0 0FFF FFF0 0FFF FFF0"		$"0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0"		$"0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0"		$"0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0 0FFF FFF0"	}};/* =======================   Size Resource ('SIZE')   ========================== */#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	isStationeryAware,	reserved, reserved, reserved, reserved,// In the best case, allow for 3 documents, the app, and some slop.// At the minimum, allow for a document, the app, and some slop.#define kPreferredNumDocuments 5	// nb, if we make this big, FracApp wants a huge partition#if qDebug	#define kAppCodeSize 350	#define kOverheadSize 100	#define kDocsize 1000	#define kSlopSize 60#else	#define kAppCodeSize 175	#define kOverheadSize 75	#define kDocsize 1000	#define kSlopSize 60#endif	(kAppCodeSize + kOverheadSize + (kDocSize * kPreferredNumDocuments) + kSlopSize) * 1024,	(kAppCodeSize + kOverheadSize + kDocSize + kSlopSize) * 1024};#endif // !MW_Rez/* ======================   Memory Resource ('mem!')   ========================= *//*	The mem! resource that MacApp uses to know how much more space we need to	reserve.  We reserve a big old 60K just for fun, so we don’t have to narrow	down the memory useage too closely.  This is big enough to cut us slack during	the big picture playbacks.  A little wasteful.  We aren’t currently using the	low space reserve, since we don’t have many commands to implement. Our memory	useage comes in big hunks so it is not as useful to watch for crossing a low	memory barrier.  We tend to run out completely or not at all. We could check	the space is low before allowing the new fractal operations, but currently it	will fail during the allocation and let the user know. Somewhat less friendly,	but adequate. The 60K number was found heuristically by examining the heap with	Macsbug to see how big the code blocks are.*//* ===========================   Menus ('CMNU')   ============================== *//*	For the menus, we set the enable flags to zero for simplicity.   The right	pieces will get enabled by the MacApp handlers (DoSetUpMenus for whatever	object can do it), so we’ll start with disabled.*/include kDefaultRsrcName   'CMNU' (mApple);		// Apple Menuresource 'CMNU' (mFile) {	mFile, textMenuProc, 0, enabled, "File", {		"New",					noIcon, "N", noMark, plain, cNew;		"New from selection",	noIcon, noKey, noMark, plain, cNewFromSelection;		"Open…",				noIcon, "O", noMark, plain, cOpen;		"-",					noIcon, noKey, noMark, plain, nocommand;		"Close",				noIcon, "W", noMark, plain, cClose;		"Save",					noIcon, "S", noMark, plain, cSave;		"Save As…",				noIcon, noKey, noMark, plain, cSaveAs;		"Save a Copy In…",		noIcon, noKey, noMark, plain, cSaveCopy;		"-",					noIcon, noKey, noMark, plain, nocommand;		"Page Setup…",			noIcon, noKey, noMark, plain, cPageSetup;		"Print One",			noIcon, noKey, noMark, plain, cPrintOne;		"Print…",				noIcon, noKey, noMark, plain, cPrint;		"-",					noIcon, noKey, noMark, plain, nocommand;		"Quit",					noIcon, "Q", noMark, plain, cQuit	}};include kDefaultRsrcName   'CMNU' (mEdit);		// Edit Menusresource 'CMNU' (mZoomy) {	mZoomy, textMenuProc, 0, enabled, "Image", {		"Zoom to Selection",			noIcon, "M", noMark, plain, cZoomToSelection;		"-",							noIcon, noKey, noMark, plain, nocommand;		"Pixel-by-Pixel algorithm",		noIcon, noKey, noMark, plain, cSlowAlgorithm;		"Mariani/Silver algorithm",		noIcon, noKey, noMark, plain, cFastAlgorithm;	}};resource 'CMNU' (mWindows) {	mWindows, textMenuProc, 0, enabled, "Windows", {	}};include kDefaultRsrcName   'CMNU' (mBuzzwords);		// Buzzwords#if qDebugresource 'MBAR' (128) { { mApple; mFile; mEdit; mZoomy; mWindows; mDebug } };#elseresource 'MBAR' (128) { { mApple; mFile; mEdit; mZoomy; mWindows } };#endif/* =====================   Selection Pattern ('PAT ')   ======================== *//*	Now the pattern that is used for the selection rectangle.*/resource 'PAT ' (128, preload, nonpurgeable) {	$"FCF9 F3E7 CF9F 3F7E"};/* ============================   Handy Strings   ============================== */resource 'STR#' (kAlgorithmStrings,#if qNames	"kAlgorithmStrings",#endif	purgeable) {	{	/* [1] */	"Using ";	/* [2] */	"unknown algorithm";	/* [3] */	"Pixel by Pixel";	/* [4] */	"Mariani/Silver";	/* [5] */	"/";	/* [6] */	"Homebrew";	/* [7] */	"32CQD";	}};/* ===========================   Error Messages   ============================== *//*	List mapping of our error code to the info string. Error messages come in four	flavors, depending on the value of the high word of the ‘message’ parameter:	msg.hiword			Message	==========			=======	msgCmdErr(0)		"Could not complete the “^2” command because ^0. ^1"							^2 = result of CmdToName(msg.loword)							^0 = LookupErrString(err, errReasonID)							^1 = LookupErrString(err, errRecoveryID)	msgAlert(-1)		Show Alert whose ID is in low word of the message.						Doesn’t call ParamText.	msgLookup(-2)		"Could not ^2 because ^0.  ^1"							^2 = LookupErrString(msg.loword, errOperationsID)							^0 = LookupErrString(err, errReasonID)							^1 = LookupErrString(err, errRecoveryID)	msgAltRecovery(-3)	"Could not ^2 because ^0.  ^1"							^2 = LookupErrString(msg.loword, errOperationsID)							^0 = LookupErrString(msg.loword, errReasonID)							^1 = LookupErrString(err, errRecoveryID)	OTHERWISE			"Could not ^2 because ^0.  ^1"							^2 = GetIndString(opString, c.hiword, c.loword)							^0 = LookupErrString(err, errReasonID)							^1 = LookupErrString(err, errRecoveryID)	NOTES:		^2 = what menu command failed (for msgCmdErr);		e.g., ‘New’.		^2 = what operation failed (for all other errors);	e.g., ‘save the document’		^0 = reason for error;		e.g., ‘the disk is locked’.		^1 = how to recover;		e.g., ‘Eject the disk and move the tab.’		^3 = gErrorParm3. You can embed ^3 into one of your substitution strings. For			instance, say you wanted to display a message that referred to a currently			open file. In that case, you could set gErrorParm3 to the name of the file,			and use one of the incantations above to set ^2 to “munge the file ^3”. That			way, ^3 will get replaced with the name of your file.		If ^2 is ever empty, the phrase ‘Could not complete your request because ^0.			^1’ is used in the dialog boxes.	So how does this “LookupErrString” business work? What MacApp does is use a	combination of ‘errs’ and ‘STR#’ resources. Each ‘errs’ resource binds itself	to a ‘STR#’ resource, and then has a list of error number ranges that map into	the strings in its ‘STR#’ resource. The basic format is a triplet: bottom range	of the error numbers, top range of the error numbers, and string index that is	associated with an error in that range. For instance, the ‘errs’ resource below	says:		“I am associated with ‘STR#’ kErrorStrings. If I am asked for the string		 associated with error kUnsupportedMac, I’ll return the string #4 in that ‘STR#’		 resource. If I am asked for the string associated with error -151 or -152, I’ll		 return the fourth string in that resource.”	Normally, MacApp looks at ‘errs’ resource 128 when it needs to fill in ^0 (the	reason for the error), 129 when it needs to fill in ^1 (how to recover), and	130 when it needs to fill in ^2 (the operation that failed). These resources	are maintained by MacApp itself.	However, MacApp first checks to see if the application wants to override or	augment those tables by first looking for resources that have the ID it wants	plus 1000. So below, we are adding to the list of reasons for the error (128 +	1000).*/resource 'errs' (errReasonID + 1000, purgeable) {	{	whichList, 0, kErrorStrings;			/* Specify to use STR# kErrorStrings */		kUnsupportedMac, kUnsupportedMac, 2;	/* error code if wrong machine. */		-152, -152, 4;						    /* translate Color Manager error to out of mem. */	}};resource 'errs' (errRecoveryID + 1000, purgeable) {	{	whichList, 0, kErrorStrings;			/* Specify to use STR# kErrorStrings */		kUnsupportedMac, kUnsupportedMac, 3;	/* error code if wrong machine. */	}};resource 'errs' (errOperationsID + 1000, purgeable) {	{	whichList, 0, kErrorStrings;			/* Specify to use STR# kErrorStrings */		kUnsupportedMac, kUnsupportedMac, 1;	/* error code if wrong machine. */	}};/* The info strings for our errors.  */resource 'STR#' (kErrorStrings,#if qNames	"kErrorStrings",#endif	purgeable) {	{	/* [1] */	"start the application";#if qPowerPC	/* [2] */	"A more expensive computer is required";#else	/* [2] */	"Color QuickDraw, a 68881 or 68882 (FPU), a 68020 microprocessor, "				"and at least System 6.0 are required";#endif	/* [3] */	"";	/* [4] */	"there is not enough memory"	}};/* used when the user attempts to run FracApp on an unsupported machine */resource 'DITL' (kUnsupportedMac,#if qNames	"kUnsupportedMac",#endif	purgeable) {	{		{120, 220, 140, 280}, Button { enabled, "OK" };		{10, 20, 42, 52}, Icon { disabled, 0 };			// stop Icon		{10, 70, 115, 280}, StaticText { disabled,#if qPowerPC			"Your computer needs to be more expensive to run FracApp." };#else			"Your computer needs Color QuickDraw, a 68881 or 68882 (FPU),"#if qNeedsMC68020			" a 68020 or 68030 microprocessor,"#endif#if qNeedsMC68030			" a 68030 microprocessor,"#endif			" and at least System 6.0 to run FracApp." };#endif	}};resource 'DITL' (kNo32BCQD,#if qNames	"kNo32BCQD",#endif	purgeable) {	{		{120, 220, 140, 280}, Button { enabled, "OK" };		{10, 20, 42, 52}, Icon { disabled, 1 };			// note Icon		{10, 70, 115, 280}, StaticText { disabled,			"FracApp performs some spiffy color animation if 32-bit Color QuickDraw "			"is installed. You don’t have it installed, so some menu items will be "			"disabled (greyed out)." };	}};resource 'ALRT' (kCompiledWrong,#if qNames	"kCompiledWrong",#endif	purgeable) {	{0, 0, 150, 400},	kCompiledWrong,	{		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;	},	alertPositionMainScreen;};resource 'DITL' (kCompiledWrong,#if qNames	"kCompiledWrong",#endif	purgeable) {	{		{120, 320, 140, 380}, Button { enabled, "OK" };		{10, 20, 42, 52}, Icon { disabled, 0 };			// stop Icon		{10, 70, 115, 380}, StaticText { disabled,			"FracApp absolutely needs to be compiled for Color QuickDraw and a Floating "			"Point co-processor. Please make sure you use the -NeedsColorQD and "			"-NeedsFPU options on your MABuild command line." };	}};resource 'ALRT' (kNoThreadManager,#if qNames	"kNoThreadManager",#endif	purgeable) {	{0, 0, 150, 400},	kNoThreadManager,	{		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;	},	alertPositionMainScreen;};resource 'DITL' (kNoThreadManager,#if qNames	"kNoThreadManager",#endif	purgeable) {	{		{120, 320, 140, 380}, Button { enabled, "OK" };		{10, 20, 42, 52}, Icon { disabled, 0 };			// stop Icon		{10, 70, 115, 380}, StaticText { disabled,			"FracApp absolutely needs the Thread Manager."};	}};resource 'ALRT' (kUnsupportedMac,#if qNames	"kUnsupportedMac",#endif	purgeable) {	{0, 0, 150, 300},	kUnsupportedMac,	{		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;		OK, visible, sound2;	},	alertPositionMainScreen;};resource 'ALRT' (kNo32BCQD,#if qNames	"kNo32BCQD",#endif	purgeable) {	{0, 0, 150, 300},	kNo32BCQD,	{		OK, visible, sound1;		OK, visible, sound1;		OK, visible, sound1;		OK, visible, sound1;	},	alertPositionMainScreen;};/* =======================   About Box Icon ('ICON')   ========================= *//* The icon used in the about box.  The same as the program ICN#, but ICON instead. */resource 'ICON' (kAbout, purgeable) {	$"0000 0001 0000 0002 0000 0004 0040 0018 0020 0418 001C 03E0 001C 03E0 001F FFE0"	$"0007 FFE0 0007 FFE0 0007 FF90 0007 FF80 FFFF FF80 FFFF FF80 DFFF FF80 EFFF FF80"	$"F1FF FF80 F1FF FF80 F1FF FFE0 FE07 FFE0 FE07 C0E0 FE07 8050 FE07 3028 FE01 C810"	$"FE0E 7F8F FFE2 3007 FFFF 0007 FFFF 8007 FFFF E007 FFFF FFE7 FFFF F01F FFFF F007"};/* =========================   Color Table ('clut')   ========================== *//*	The brave new approach.  This will be the clut resource that we use to do the	color table for the offscreen bitmap.  This is a set of colors that we	specifically want in our bitmap, the only ones that we use. This table has all	the artificial requirements that a color table normally has, like having white	first, black last. This color table is the one really desired for the actual	fractals, so it will be used only for the offscreen map.  Resource Id is to be	in 0..1023 to start with, since it will become the initial ctSeed number.*/resource 'clut' (kClut,#if qNames	"kClut",#endif	preload) { 	0x0,			/* seed number for this table, left zero for resources */ 	0xC000,			/* ctFlags: for gDevice, animating colors */	{/*	Now the actual colors in the table. Look at what we set the colorSpec.value	fields to. These values reference the animated entries in the palette we use	for our windows; they are the ones we want to match when we Copybits our	offscreen stuff to the window.*//* [1] */	0x00, 0xFFFF, 0xFFFF, 0xFFFF,	/* first color must be white of course. *//* [2] */	0x10, 0xFFFF, 0x0000, 0x0000,/* [3] */	0x11, 0xFFFF, 0x0400, 0x0000,/* [4] */	0x12, 0xFFFF, 0x0800, 0x0000,/* [5] */	0x13, 0xFFFF, 0x0C00, 0x0000,/* [6] */	0x14, 0xFFFF, 0x1000, 0x0000,/* [7] */	0x15, 0xFFFF, 0x1400, 0x0000,/* [8] */	0x16, 0xFFFF, 0x1800, 0x0000,/* [9] */	0x17, 0xFFFF, 0x1C00, 0x0000,/* [10] */	0x18, 0xFFFF, 0x2000, 0x0000,/* [11] */	0x19, 0xFFFF, 0x2400, 0x0000,/* [12] */	0x1A, 0xFFFF, 0x2800, 0x0000,/* [13] */	0x1B, 0xFFFF, 0x2C00, 0x0000,/* [14] */	0x1C, 0xFFFF, 0x3000, 0x0000,/* [15] */	0x1D, 0xFFFF, 0x3400, 0x0000,/* [16] */	0x1E, 0xFFFF, 0x3800, 0x0000,/* [17] */	0x1F, 0xFFFF, 0x3C00, 0x0000,/* [18] */	0x20, 0xFFFF, 0x4000, 0x0000,/* [19] */	0x21, 0xFFFF, 0x4400, 0x0000,/* [20] */	0x22, 0xFFFF, 0x4800, 0x0000,/* [21] */	0x23, 0xFFFF, 0x4C00, 0x0000,/* [22] */	0x24, 0xFFFF, 0x5000, 0x0000,/* [23] */	0x25, 0xFFFF, 0x5400, 0x0000,/* [24] */	0x26, 0xFFFF, 0x5800, 0x0000,/* [25] */	0x27, 0xFFFF, 0x5C00, 0x0000,/* [26] */	0x28, 0xFFFF, 0x6000, 0x0000,/* [27] */	0x29, 0xFFFF,